FormatToBuf.example:
#include <cinux/format.hpp>

using namespace cinux::base::format;

void WriteUnsigned() {
    char text[32];
    const Arg kArguments[] = {NumU(4096)};
    FormatToBuf(text, sizeof text, "%u", ArgsView::of(kArguments));
    // text = "4096" · 参数按数组顺序取用
}

VformatToBuf.example:
#include <cinux/format.hpp>

using namespace cinux::base::format;

void TruncateSafely() {
    char text[5];
    VformatToBuf(text, sizeof text, "%s", "cinux");
    // text = "cinu" · 放不下时截断，末尾始终留一个 NUL
}
